import { Button } from '@arco-design/web-react';
import React, { useRef, useState } from 'react';
import CTour from '..';
import type { CTourStepInfo } from '../interface';

function getStyle(top: number, left: number): React.CSSProperties {
  return {
    position: 'absolute',
    top,
    left,
  };
}

const config = [
  { position: 'tl', placement: [0, 70] },
  { position: 'top', placement: [0, 180] },
  { position: 'tr', placement: [0, 290] },
  { position: 'lt', placement: [60, 10] },
  { position: 'left', placement: [120, 10] },
  { position: 'lb', placement: [180, 10] },
  { position: 'rt', placement: [60, 350] },
  { position: 'right', placement: [120, 350] },
  { position: 'rb', placement: [180, 350] },
  { position: 'bl', placement: [240, 70] },
  { position: 'bottom', placement: [240, 180] },
  { position: 'br', placement: [240, 290] },
] as const;

export default () => {
  const ref = useRef<(unknown | null)[]>([]);
  const [open, setOpen] = useState(false);
  const [current, setCurrent] = useState(0);

  const steps = config.map(
    (p, i): CTourStepInfo => ({
      title: '这里是标题',
      desc: '这里是描述描述描述描述描述描述描述描述',
      target: () => ref.current[i] as HTMLElement,
      position: p.position,
    }),
  );

  return (
    <>
      <div
        style={{
          position: 'relative',
          margin: 200,
          width: 440,
          height: 280,
        }}
      >
        {config.map(({ placement, position }, i) => (
          <Button
            key={position}
            ref={v => (ref.current[i] = v)}
            style={getStyle(placement[0], placement[1])}
            onClick={() => {
              setOpen(true);
              setCurrent(i);
            }}
          >
            {position}
          </Button>
        ))}
      </div>
      {
        <CTour
          steps={steps}
          open={open}
          current={current}
          onFinish={() => setOpen(false)}
          onClose={() => setOpen(false)}
          onChange={setCurrent}
        />
      }
    </>
  );
};

import React, { useRef, useState } from 'react';
import { MemoryRouter, Route, Switch, useHistory, useLocation } from 'react-router-dom';
import { Button, CTour, Input, Space, Tag } from '@cloud-materials/common';
import type { CTourStepInfo } from '../interface';
import type { RefInputType } from '@arco-design/web-react/es/Input';

const Page1 = () => {
  const [open, setOpen] = useState(false);
  const btnRef = useRef<HTMLButtonElement>(null);
  const history = useHistory();
  const tourProps: CTourStepInfo[] = [
    {
      title: '这是第一个引导卡片',
      desc: '这是第一个引导，什么都有。',
      target: () => btnRef.current,
    },
    {
      desc: '可以不填，因为只是占位用',
    },
  ];

  return (
    <Space>
      <Button
        type="primary"
        ref={btnRef}
        onClick={() => {
          setOpen(true);
        }}
      >
        开始引导
      </Button>
      <CTour
        steps={tourProps}
        open={open}
        onChange={current => {
          if (current === 1) {
            history.push('/page2');
          }
        }}
      />
    </Space>
  );
};

const Page2 = () => {
  const inputRef = useRef<RefInputType>(null);
  const history = useHistory();
  const tourProps: CTourStepInfo[] = [
    {
      desc: '可以不填，因为只是占位用',
    },
    {
      title: '这是第二个引导卡片',
      desc: '你没法点上一步回去了，只能点完成了',
      target: () => inputRef.current?.dom,
      prevButtonProps: { style: { display: 'none' } },
    },
  ];
  return (
    <Space>
      <Button
        onClick={() => {
          history.push('/page1');
        }}
      >
        重新开始
      </Button>
      <Input type="primary" ref={inputRef} placeholder="这里是第二页的内容了" />
      <CTour defaultCurrent={1} steps={tourProps} defaultOpen />
    </Space>
  );
};

const CurrentPath = () => {
  const location = useLocation();
  return (
    <div style={{ marginBottom: 20 }}>
      <Tag size="large">当前路径：{location.pathname}</Tag>
    </div>
  );
};

export default () => {
  return (
    <MemoryRouter initialEntries={['/page1']}>
      <CurrentPath />
      <Switch>
        <Route path="/page1" component={Page1} />
        <Route path="/page2" component={Page2} />
      </Switch>
    </MemoryRouter>
  );
};
